20	// 获取当前 UTC 时间 ISO 8601 字符串，例如 2026-10-20T12:00:00.000Z
21	std::string CurrentIsoTimestamp() {
22	  const auto now = std::chrono::system_clock::now();
23	  const auto millis = std::chrono::duration_cast<std::chrono::milliseconds>(
24	                          now.time_since_epoch()) %
25	                      1000;
26	  const std::time_t timer = std::chrono::system_clock::to_time_t(now);
27	  std::tm tm_buf{};
28	#if defined(_WIN32)
29	  gmtime_s(&tm_buf, &timer);
30	#else
31	  gmtime_r(&timer, &tm_buf);
32	#endif
33	  std::ostringstream ss;
34	  ss << std::put_time(&tm_buf, "%Y-%m-%dT%H:%M:%S") << '.'
35	     << std::setfill('0') << std::setw(3) << millis.count() << 'Z';
36	  return ss.str();
37	}
