39	std::string EscapeJsonString(const std::string& input) {
40	  std::string out;
41	  out.reserve(input.size() + 8);
42	  for (const char c : input) {
43	    switch (c) {
44	      case '"':
45	        out += "\\\"";
46	        break;
47	      case '\\':
48	        out += "\\\\";
49	        break;
50	      case '\b':
51	        out += "\\b";
52	        break;
53	      case '\f':
54	        out += "\\f";
55	        break;
56	      case '\n':
57	        out += "\\n";
58	        break;
59	      case '\r':
60	        out += "\\r";
61	        break;
62	      case '\t':
63	        out += "\\t";
64	        break;
65	      default:
66	        out += c;
67	        break;
68	    }
69	  }
70	  return out;
71	}
