349	std::string SerializeVda5050Order(const VehicleOrder& order, const std::string& version) {
350	  std::ostringstream ss;
351	  const std::string vda_version = (version == "v3") ? "3.0.0" : "2.0.0";
352	  const std::string timestamp = CurrentIsoTimestamp();
353	
354	  ss << "{";
355	  ss << "\"headerId\":0,";
356	  ss << "\"timestamp\":\"" << timestamp << "\",";
357	  ss << "\"version\":\"" << vda_version << "\",";
358	  ss << "\"manufacturer\":\"RobotManufacturer\",";
359	  ss << "\"serialNumber\":\"" << EscapeJsonString(order.vehicle_id) << "\",";
360	  ss << "\"orderId\":\"" << EscapeJsonString(order.order_id) << "\",";
361	  ss << "\"orderUpdateId\":" << order.order_update_id << ",";
362	
363	  // nodes
364	  ss << "\"nodes\":[";
365	  for (size_t i = 0; i < order.nodes.size(); ++i) {
366	    if (i > 0) ss << ",";
367	    const auto& node = order.nodes[i];
368	    ss << "{";
369	    ss << "\"nodeId\":\"" << EscapeJsonString(node.node_id) << "\",";
370	    ss << "\"sequenceId\":" << node.sequence_id << ",";
371	    ss << "\"released\":" << (node.released ? "true" : "false") << ",";
372	    ss << "\"nodePosition\":{";
373	    ss << "\"x\":" << FormatDouble(node.x) << ",";
374	    ss << "\"y\":" << FormatDouble(node.y) << ",";
375	    ss << "\"theta\":" << FormatDouble(node.yaw) << ",";
376	    ss << "\"mapId\":\"map\"";
377	    ss << "},";
378	    ss << "\"actions\":[";
379	    for (size_t a = 0; a < node.actions.size(); ++a) {
380	      if (a > 0) ss << ",";
381	      const auto& act = node.actions[a];
382	      ss << "{";
383	      ss << "\"actionType\":\"" << EscapeJsonString(act.action_type) << "\",";
384	      ss << "\"actionId\":\"" << EscapeJsonString(act.action_id) << "\",";
385	      ss << "\"blockingType\":\"HARD\",";
386	      ss << "\"actionParameters\":[";
387	      size_t p_idx = 0;
388	      for (const auto& [k, v] : act.parameters) {
389	        if (p_idx > 0) ss << ",";
390	        ss << "{\"key\":\"" << EscapeJsonString(k) << "\",\"value\":\""
391	           << EscapeJsonString(v) << "\"}";
392	        ++p_idx;
393	      }
394	      ss << "]";
395	      ss << "}";
396	    }
397	    ss << "]";
398	    ss << "}";
399	  }
400	  ss << "],";
401	
402	  // edges
403	  ss << "\"edges\":[";
404	  for (size_t i = 0; i < order.edges.size(); ++i) {
405	    if (i > 0) ss << ",";
406	    const auto& edge = order.edges[i];
407	    ss << "{";
408	    ss << "\"edgeId\":\"" << EscapeJsonString(edge.edge_id) << "\",";
409	    ss << "\"sequenceId\":" << (i * 2 + 2) << ",";  // edge sequence id
410	    ss << "\"startNodeId\":\"" << EscapeJsonString(edge.start_node_id) << "\",";
411	    ss << "\"endNodeId\":\"" << EscapeJsonString(edge.end_node_id) << "\",";
412	    ss << "\"released\":" << (edge.released ? "true" : "false") << ",";
413	    ss << "\"maxSpeed\":" << FormatDouble(edge.max_speed) << ",";
414	
415	    // trajectory
416	    ss << "\"trajectory\":{";
417	    ss << "\"degree\":1,";
418	    ss << "\"controlPoints\":[";
419	    for (size_t p = 0; p < edge.polyline.size(); ++p) {
420	      if (p > 0) ss << ",";
421	      ss << "{";
422	      ss << "\"x\":" << FormatDouble(edge.polyline[p].x) << ",";
423	      ss << "\"y\":" << FormatDouble(edge.polyline[p].y) << ",";
424	      ss << "\"theta\":" << FormatDouble(edge.polyline[p].yaw);
425	      ss << "}";
426	    }
427	    ss << "]";
428	    ss << "},";
429	
430	    // actions
431	    ss << "\"actions\":[";
432	    for (size_t a = 0; a < edge.actions.size(); ++a) {
433	      if (a > 0) ss << ",";
434	      const auto& act = edge.actions[a];
435	      ss << "{";
436	      ss << "\"actionType\":\"" << EscapeJsonString(act.action_type) << "\",";
437	      ss << "\"actionId\":\"" << EscapeJsonString(act.action_id) << "\",";
438	      ss << "\"blockingType\":\"HARD\",";
439	      ss << "\"actionParameters\":[";
440	      size_t p_idx = 0;
441	      for (const auto& [k, v] : act.parameters) {
442	        if (p_idx > 0) ss << ",";
443	        ss << "{\"key\":\"" << EscapeJsonString(k) << "\",\"value\":\""
444	           << EscapeJsonString(v) << "\"}";
445	        ++p_idx;
446	      }
447	      ss << "]";
448	      ss << "}";
449	    }
450	    ss << "]";
451	    ss << "}";
452	  }
453	  ss << "]";
454	
455	  ss << "}";
456	  return ss.str();
457	}
458	
459	std::string SerializeVda5050InstantActions(const std::string& vehicle_id,
460	                                          const std::vector<VehicleAction>& actions,
461	                                          const std::string& version) {
462	  std::ostringstream ss;
463	  const std::string vda_version = (version == "v3") ? "3.0.0" : "2.0.0";
464	  const std::string timestamp = CurrentIsoTimestamp();
465	
466	  ss << "{";
467	  ss << "\"headerId\":0,";
468	  ss << "\"timestamp\":\"" << timestamp << "\",";
469	  ss << "\"version\":\"" << vda_version << "\",";
470	  ss << "\"manufacturer\":\"RobotManufacturer\",";
471	  ss << "\"serialNumber\":\"" << EscapeJsonString(vehicle_id) << "\",";
472	  ss << "\"actions\":[";
473	  for (size_t i = 0; i < actions.size(); ++i) {
474	    if (i > 0) ss << ",";
475	    const auto& act = actions[i];
476	    ss << "{";
477	    ss << "\"actionType\":\"" << EscapeJsonString(act.action_type) << "\",";
478	    ss << "\"actionId\":\"" << EscapeJsonString(act.action_id) << "\",";
479	    ss << "\"blockingType\":\"HARD\",";
480	    ss << "\"actionParameters\":[";
481	    size_t p_idx = 0;
482	    for (const auto& [k, v] : act.parameters) {
483	      if (p_idx > 0) ss << ",";
484	      ss << "{\"key\":\"" << EscapeJsonString(k) << "\",\"value\":\""
485	         << EscapeJsonString(v) << "\"}";
486	      ++p_idx;
487	    }
488	    ss << "]";
489	    ss << "}";
490	  }
491	  ss << "]";
492	  ss << "}";
493	  return ss.str();
494	}
