class MiniJsonParser {
 public:
  explicit MiniJsonParser(std::string_view text) : text_(text), pos_(0) {}

  std::optional<JsonValue> Parse() {
    SkipWhitespace();
    if (pos_ >= text_.size()) {
      return std::nullopt;
    }
    auto val = ParseValue();
    if (!val.has_value()) {
      return std::nullopt;
    }
    SkipWhitespace();
    if (pos_ != text_.size()) {
      return std::nullopt;  // 尾部有多余非空白字符
    }
    return val;
  }

 private:
