      val.obj_val.emplace(std::move(key), std::move(*member_val));

      SkipWhitespace();
      char sep = Peek();
      if (sep == ',') {
        Next();
      } else if (sep == '}') {
        Next();
        return val;
      } else {
        return std::nullopt;
      }
    }
    return std::nullopt;
  }

  std::optional<JsonValue> ParseArray() {
    if (Next() != '[') return std::nullopt;
    JsonValue val;
    val.type = JsonType::Array;
    SkipWhitespace();
    if (Peek() == ']') {
      Next();
      return val;
